export const MEMBER_RATE = 0.8;
export const BIG_EVENT_SEATS = 40;
export const BIG_EVENT_FEE = 100000;
export const LONG_EVENT_HOURS = 4;
export const LONG_EVENT_DISCOUNT = 50000;

